macro_rules! deps {
    () => {
        PlaceRef!();
        PlaceValue!();
    };
}

macro_rules! OperandValue {
    () => {
        deps!();
        # [doc = " The representation of a Rust value. The enum variant is in fact"] # [doc = " uniquely determined by the value's type, but is kept as a"] # [doc = " safety check."] # [derive (Copy , Clone , Debug)] pub enum OperandValue < V > { # [doc = " A reference to the actual operand. The data is guaranteed"] # [doc = " to be valid for the operand's lifetime."] # [doc = " The second value, if any, is the extra data (vtable or length)"] # [doc = " which indicates that it refers to an unsized rvalue."] # [doc = ""] # [doc = " An `OperandValue` *must* be this variant for any type for which"] # [doc = " [`LayoutTypeCodegenMethods::is_backend_ref`] returns `true`."] # [doc = " (That basically amounts to \"isn't one of the other variants\".)"] # [doc = ""] # [doc = " This holds a [`PlaceValue`] (like a [`PlaceRef`] does) with a pointer"] # [doc = " to the location holding the value. The type behind that pointer is the"] # [doc = " one returned by [`LayoutTypeCodegenMethods::backend_type`]."] Ref (PlaceValue < V >) , # [doc = " A single LLVM immediate value."] # [doc = ""] # [doc = " An `OperandValue` *must* be this variant for any type for which"] # [doc = " [`LayoutTypeCodegenMethods::is_backend_immediate`] returns `true`."] # [doc = " The backend value in this variant must be the *immediate* backend type,"] # [doc = " as returned by [`LayoutTypeCodegenMethods::immediate_backend_type`]."] Immediate (V) , # [doc = " A pair of immediate LLVM values. Used by wide pointers too."] # [doc = ""] # [doc = " # Invariants"] # [doc = " - For `Pair(a, b)`, `a` is always at offset 0, but may have `FieldIdx(1..)`"] # [doc = " - `b` is not at offset 0, because `V` is not a 1ZST type."] # [doc = " - `a` and `b` will have a different FieldIdx, but otherwise `b`'s may be lower"] # [doc = "   or they may not be adjacent, due to arbitrary numbers of 1ZST fields that"] # [doc = "   will not affect the shape of the data which determines if `Pair` will be used."] # [doc = " - An `OperandValue` *must* be this variant for any type for which"] # [doc = " [`LayoutTypeCodegenMethods::is_backend_scalar_pair`] returns `true`."] # [doc = " - The backend values in this variant must be the *immediate* backend types,"] # [doc = " as returned by [`LayoutTypeCodegenMethods::scalar_pair_element_backend_type`]"] # [doc = " with `immediate: true`."] Pair (V , V) , # [doc = " A value taking no bytes, and which therefore needs no LLVM value at all."] # [doc = ""] # [doc = " If you ever need a `V` to pass to something, get a fresh poison value"] # [doc = " from [`ConstCodegenMethods::const_poison`]."] # [doc = ""] # [doc = " An `OperandValue` *must* be this variant for any type for which"] # [doc = " `is_zst` on its `Layout` returns `true`. Note however that"] # [doc = " these values can still require alignment."] ZeroSized , }
    };
}

OperandValue!()